// Allocate 10 bytes (generic data block)
void* block = malloc(10);
if (block == NULL) { /* Handle error */ }

// Specific type pointer assignment
int* data = (int*)malloc(sizeof(int));

// Pointer assignment and usage
if (data) *data = 99;

// Mandatory Deallocation
free(data);
data = NULL; // Prevent dangling pointer

free(block);
block = NULL;

// Safe double free check (although free(NULL) is safe)
if (data != NULL) free(data);
